// Step 1: Extract & Sanitize incoming WhatsApp message payload
const body = $input.first().json.body || {};
const data = body.data || {};

const rawText = data.body || body.message || body.text || '';
const chatId = data.chatId || data.from || body.chatId || '';
const senderName = data.sender?.pushname || data.sender?.name || 'Patient';
const sessionId = body.sessionId || 'wp-session-' + (chatId ? chatId.replace(/[^0-9]/g, '') : Date.now());

// Normalize phone number (strip @c.us, +, and non-digits)
const senderPhone = (chatId || '').replace(/@c\.us/g, '').replace(/[^0-9]/g, '');

return {
  text: rawText.trim(),
  chatId,
  senderPhone,
  senderName,
  sessionId,
  timestamp: new Date().toISOString()
};

// Step 3: Intent Classification (Emergency Triage, Medical Records, or General Query)
const parserData = $('Message Parser').first().json;
const authPayload = $input.first().json;
const authData = authPayload.data || authPayload;
const text = (parserData.text || '').toLowerCase();

// Check if backend connection failed
const isBackendDown = Boolean(authPayload.error || (authPayload.code && authPayload.code.includes('ECONN')));

// 1. Emergency Red-Flag detection (Always prioritized, even if backend is offline)
const emergencyKeywords = [
  'chest pain', 'cannot breathe', "can't breathe", 'gasping', 'shortness of breath',
  'severe bleeding', 'vomiting blood', 'stroke', 'paralysis', 'unconscious',
  'fainted', 'loss of consciousness', 'heart attack', 'છાતીમાં દુખાવો', 'શ્વાસ', 'બેભાન', 'લોહી', 'सीना दर्द', 'सांस'
];
const isEmergency = emergencyKeywords.some(k => text.includes(k));

// 2. Medical Record Required detection
const recordKeywords = [
  'report', 'blood report', 'sugar', 'hba1c', 'bp', 'prescription', 'medicine api hati',
  'doctor e su lakhyu', 'mara reports', 'last checkup', 'previous diagnosis', 'medical history',
  'file', 'lab test', 'doctor notes', 'રિપોર્ટ', 'દવા', 'પ્રેસ્ક્રિપ્શન', 'તપાસ', 'दवा', 'जांच', 'पर्चा'
];
const isRecordQuery = recordKeywords.some(k => text.includes(k));

let intent = 'GENERAL_QUERY';
if (isEmergency) {
  intent = 'EMERGENCY_TRIAGE';
} else if (isRecordQuery) {
  intent = 'MEDICAL_RECORD_REQUIRED';
}

return {
  text: parserData.text,
  chatId: parserData.chatId,
  senderPhone: parserData.senderPhone,
  senderName: parserData.senderName,
  sessionId: parserData.sessionId,
  authenticated: Boolean(authData.authenticated),
  patient: authData.patient || null,
  session: authData.session || null,
  has_consent: Boolean(authData.has_consent),
  isBackendDown,
  intent
};

// Emergency / Triage Safety Response Generator
const item = $input.first().json;

const output = `🚨 *EMERGENCY TRIAGE ALERT*\n\n` +
  `Tamara symptoms (Severe chest pain / breathing problem / stroke signs) tatkalik emergency doctor examination mange che.\n\n` +
  `⚠️ *WhatsApp chat par wait na karo!*\n` +
  `• Immediately Emergency Ambulance call karo: *108 / 102*\n` +
  `• Najik na Trauma Center athva Hospital Emergency Room ma pahoncho\n` +
  `• MediKiosk Hospital Desk: *079-26578900*\n\n` +
  `Hospital emergency triage team ne alert generate kari didho che.`;

return {
  chatId: item.chatId,
  sessionId: item.sessionId,
  output,
  isEmergency: true
};

// Record Formatter & DPDP Consent Gate Validator
const recordsResponse = $input.first().json;
const intentData = $('Intent Evaluator').first().json;

// Check if backend connection failed
if (recordsResponse.error || (recordsResponse.code && recordsResponse.code.includes('ECONN'))) {
  return {
    chatId: intentData.chatId,
    sessionId: intentData.sessionId,
    skipAgent: true,
    directOutput: 'Hospital medical records server sathe atyare sampark nathi thai shakto. Krupaya thodi vaar pachi prayas karo athva hospital helpdesk par contact karo.'
  };
}

// Check authorization (handles both flat and data-wrapped response envelopes)
const isAuthorized = recordsResponse.authorized === true || recordsResponse.data?.authorized === true;
const rec = recordsResponse.data?.records || recordsResponse.records;
const patientInfo = recordsResponse.data?.patient || recordsResponse.patient;

if (!isAuthorized || !rec) {
  // Access restricted or consent revoked
  const safeMessage = recordsResponse.message || 'Hu tamaru medical record access kari shaktu nathi atyare, because proper verification/authorization required che.';
  return {
    chatId: intentData.chatId,
    sessionId: intentData.sessionId,
    skipAgent: true,
    directOutput: safeMessage
  };
}

const latest = rec.latest_record;
const obs = rec.observations || {};

let recordSummary = `PATIENT: ${patientInfo?.name || 'Verified Patient'}\n`;
if (latest) {
  recordSummary += `RECORD DATE: ${latest.reviewed_at || 'Recent OPD Visit'}\n`;
  recordSummary += `CHIEF COMPLAINT: ${latest.chief_complaint || 'N/A'}\n`;
  recordSummary += `DOCTOR NOTES: ${latest.doctor_notes || 'N/A'}\n`;
  if (latest.prescriptions && latest.prescriptions.length > 0) {
    recordSummary += `PRESCRIBED MEDICINES:\n`;
    latest.prescriptions.forEach(p => {
      recordSummary += `- ${p.medicine_name} (${p.dosage || ''}), ${p.frequency || ''} for ${p.duration || ''}. ${p.instructions || ''}\n`;
    });
  }
  if (latest.lab_investigations && latest.lab_investigations.length > 0) {
    recordSummary += `LAB INVESTIGATIONS:\n`;
    latest.lab_investigations.forEach(l => {
      recordSummary += `- ${l.test_name}: ${l.observed_value} ${l.unit || ''} (Ref: ${l.reference_range || ''}) Flag: ${l.flag || 'Normal'}\n`;
    });
  }
}

if (obs.symptoms && obs.symptoms.length > 0) {
  recordSummary += `OBSERVED SYMPTOMS: ${obs.symptoms.map(s => `${s.name} (${s.value || ''})`).join(', ')}\n`;
}
if (obs.conditions && obs.conditions.length > 0) {
  recordSummary += `DOCUMENTED CONDITIONS: ${obs.conditions.join(', ')}\n`;
}

return {
  chatId: intentData.chatId,
  sessionId: intentData.sessionId,
  userQuestion: intentData.text,
  patientId: intentData.patient?.patient_id || '',
  recordsContext: recordSummary,
  skipAgent: false
};

// Step: Post-Generation Safety Validation Firewall
const item = $input.first().json;

// Safely check if Record Formatter had skipped the agent (handles both execution paths)
let formatterItem = null;
try {
  formatterItem = $('Record Formatter').first()?.json || null;
} catch (e) {
  formatterItem = null;
}

if (formatterItem && formatterItem.skipAgent) {
  return {
    chatId: formatterItem.chatId,
    sessionId: formatterItem.sessionId,
    validatedText: formatterItem.directOutput
  };
}

let output = item.output || '';

// If LLM output echoed SKIP
if (output.startsWith('SKIP:')) {
  output = output.replace(/^SKIP:\s*/i, '');
}

// 1. Block unauthorized dosage prescription attempts
if (/(take|prescribe)\s+\d+\s*(mg|ml|tablets?)\s+\d+\s*times/i.test(output)) {
  output = output.replace(/(take|prescribe)\s+\d+\s*(mg|ml|tablets?)\s+\d+\s*times/gi, 'take as advised by your doctor');
}

// 2. Prevent system prompt, connection string, or schema leaks
if (/system_directives|systemMessage|MONGO_URI|JWT_SECRET|host\.docker\.internal/i.test(output)) {
  output = 'Tamara medical record sambandhit mahiti mate krupaya hospital helpdesk athva consulting doctor no sampark karo.';
}

const parserJson = $('Message Parser').first().json;

return {
  chatId: parserJson.chatId,
  sessionId: parserJson.sessionId,
  validatedText: output.trim()
};

// Step: Gujlish Formatter — Ensures natural conversational tone in Roman Gujlish
const item = $input.first().json;
let text = item.validatedText || '';

// Clean up robotic prefixes
text = text
  .replace(/^Certainly!\s*/i, '')
  .replace(/^How may I assist you\?\s*/i, '')
  .replace(/^As an AI health assistant,\s*/i, '');

// Ensure courteous closing if not present and text is non-empty
if (text && !text.includes('doctor') && !text.includes('ડોક્ટર')) {
  text += '\n\n_Vadhare jankari mate OPD doctor ni consultation helpful raheshe._';
}

return {
  chatId: item.chatId,
  sessionId: item.sessionId,
  output: text.trim()
};
